<script setup lang="ts">import { Head,Link } from '@inertiajs/vue3';defineProps<{receivables:{data:any[]};canManage:boolean}>();const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v||0);</script><template><Head title="Cuentas por cobrar"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Cuentas por cobrar</h1><p class="text-sm text-muted-foreground">Los abonos reducen cartera y aumentan caja o banco; no crean otra venta.</p></header><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Documento</th><th class="px-4 py-3">Cliente</th><th class="px-4 py-3">Vencimiento</th><th class="px-4 py-3">Original</th><th class="px-4 py-3">Saldo</th><th></th></tr></thead><tbody class="divide-y"><tr v-for="item in receivables.data" :key="item.id"><td class="px-4 py-3">{{item.document_number}}</td><td class="px-4 py-3">{{item.customer}}</td><td class="px-4 py-3">{{item.due_at||'Sin fecha'}}</td><td class="px-4 py-3">{{money(item.original_amount)}}</td><td class="px-4 py-3 font-medium">{{money(item.balance_amount)}}</td><td class="px-4 py-3 text-right"><Link v-if="canManage" :href="`/receivables/${item.id}/pay`" class="font-medium text-amber-700 hover:underline">Registrar abono</Link></td></tr></tbody></table><p v-if="!receivables.data.length" class="p-10 text-center text-sm text-muted-foreground">No hay cartera pendiente.</p></section></main></template>
